// Guard scanned PDFs (no text layer -> needs OCR, out of scope v1) and build the Claude request body here.
// Building JSON in a Code node avoids n8n's expression parser choking on "}}" inside object literals.
const SYSTEM = 'You extract structured data from invoice text. Return only the fields in the schema. Dates as YYYY-MM-DD. Amounts as plain numbers without currency symbols. line_items amount = quantity * unit_price. subtotal = sum of amounts. total = subtotal + tax. If a field is genuinely absent use null (due_date) or 0 (tax). Do not invent values.';
const SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['vendor','invoice_number','invoice_date','due_date','currency','subtotal','tax','total','line_items'],
  properties: {
    vendor: { type: 'string' }, invoice_number: { type: 'string' },
    invoice_date: { type: 'string', description: 'YYYY-MM-DD' }, due_date: { type: ['string','null'] },
    currency: { type: 'string', description: 'ISO 4217' },
    subtotal: { type: 'number' }, tax: { type: 'number' }, total: { type: 'number' },
    line_items: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['description','quantity','unit_price','amount'],
      properties: { description: { type: 'string' }, quantity: { type: 'number' }, unit_price: { type: 'number' }, amount: { type: 'number' } } } }
  }
};
const files = $('Read PDFs from folder').all();
const out = [];
$input.all().forEach((item, i) => {
  const text = (item.json.text || '').trim();
  const file = files[i]?.binary?.data?.fileName || item.binary?.data?.fileName || `file-${i + 1}.pdf`;
  if (text.length < 40) {
    out.push({ json: { file, error: 'no text layer (scanned PDF?)', skip: true } });
    return;
  }
  const request = {
    model: $env.INVOICE_MODEL || 'claude-sonnet-5',
    max_tokens: 2048,
    system: SYSTEM,
    messages: [{ role: 'user', content: '<invoice>\n' + text + '\n</invoice>' }],
    output_config: { format: { type: 'json_schema', schema: SCHEMA } }
  };
  out.push({ json: { file, text, skip: false, request } });
});
return out;

// Parse the structured-output text block and reconcile totals (same rules as extractor/schema.py).
const out = [];
const srcs = $('Guard: has text?').all().filter(s => !s.json.skip); // positional pairing (run-once-for-all mode)
$input.all().forEach((item, i) => {
  const file = srcs[i]?.json.file || `item-${i + 1}`;
  try {
    const block = (item.json.content || []).find(b => b.type === 'text');
    if (!block) throw new Error('no text block in response (stop_reason=' + item.json.stop_reason + ')');
    const inv = JSON.parse(block.text);
    const r2 = n => Math.round(n * 100) / 100;
    const itemsSum = r2(inv.line_items.reduce((s, li) => s + li.amount, 0));
    if (Math.abs(itemsSum - inv.subtotal) > 0.02) throw new Error(`line items ${itemsSum} != subtotal ${inv.subtotal}`);
    if (Math.abs(r2(inv.subtotal + inv.tax) - inv.total) > 0.02) throw new Error(`subtotal+tax != total ${inv.total}`);
    if (inv.due_date && inv.due_date < inv.invoice_date) throw new Error('due_date before invoice_date');
    out.push({ json: {
      file, vendor: inv.vendor, invoice_number: inv.invoice_number, invoice_date: inv.invoice_date,
      due_date: inv.due_date || '', currency: (inv.currency || 'USD').toUpperCase(),
      subtotal: inv.subtotal, tax: inv.tax, total: inv.total,
      line_items: inv.line_items.map(li => `${li.quantity} x ${li.description} @ ${li.unit_price.toFixed(2)}`).join('; '),
      input_tokens: item.json.usage?.input_tokens, output_tokens: item.json.usage?.output_tokens,
      error: ''
    } });
  } catch (e) {
    out.push({ json: { file, error: e.message } });
  }
});
return out;

// One summary line for the run; goes to Slack/email. Failed files are listed so nothing is silently lost.
const rows = $('Validate + flatten').all().map(i => i.json);
const skipped = $('Guard: has text?').all().map(i => i.json).filter(j => j.skip);
const ok = rows.filter(r => !r.error);
const bad = rows.filter(r => r.error).concat(skipped);
const sum = ok.reduce((s, r) => s + (r.total || 0), 0);
const lines = [
  `Invoice run: ${ok.length} extracted, ${bad.length} need attention`,
  ...ok.map(r => `  OK ${r.file}: ${r.vendor} #${r.invoice_number} ${r.currency} ${r.total.toFixed(2)} due ${r.due_date || 'n/a'}`),
  ...bad.map(r => `  !! ${r.file}: ${r.error}`),
  `Total booked: ${sum.toFixed(2)}`
];
return [{ json: { text: lines.join('\n'), ok: ok.length, failed: bad.length } }];
